CREATE ALGORITHM=UNDEFINED DEFINER=`jedieduca`@`%` SQL SECURITY DEFINER VIEW `alunoview`  AS  select `su`.`id` AS `id`,`su`.`name` AS `name`,`su`.`login` AS `login`,`su`.`email` AS `email`,`tof`.`denominacao` AS `turma` from ((((`system_user` `su` left join `system_user_group` `sug` on((`su`.`id` = `sug`.`system_user_id`))) left join `ofertaturmaaluno` `ota` on((`su`.`id` = `ota`.`idaluno`))) left join `turmaoferta` `tof` on((`ota`.`idofertaturma` = `tof`.`id`))) left join `turma` `t` on((`tof`.`idturma` = `t`.`id`))) where (`sug`.`system_group_id` = 4) ;

